contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount > 0);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.sudicideAnyone{value: amount}() { reverted = false; }
        catch { reverted = true; }
        assert(reverted && address(c).balance == balBefore);
    }
    receive() external payable {}
}
